// Keyboard walk of the incumbent Invoices queue + in-page detector counts. Evidence for #240.
import { chromium } from "playwright"

const WS = "af91555d-7450-4b21-a8ac-73db092617c8"
const base = `http://localhost:3000/workspaces/${WS}`
const browser = await chromium.launch()
const out = {}

async function describeFocus(page) {
  return page.evaluate(() => {
    const el = document.activeElement
    if (!el || el === document.body) return "body"
    const label = el.getAttribute("aria-label") || el.textContent?.trim().slice(0, 40) || ""
    return `${el.tagName.toLowerCase()}${el.id ? "#" + el.id : ""}[${el.getAttribute("role") || ""}] "${label}"`
  })
}

async function detector(page) {
